INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15944, 'FDA Notices Issued Over Vimal Elaichi Advertisement', 'विमल इलायची विज्ञापन पर FDA ने जारी किए नोटिस', 'Maharashtra''s Food and Drug Administration (FDA) has issued notices to actors Shah Rukh Khan, Ajay Devgn, and Tiger Shroff regarding an advertisement for Vimal Elaichi. The FDA has warned the actors over their endorsement of the product. Actor Mukesh Khanna has supported the FDA''s action, stating the actors should apologize.', 'महाराष्ट्र के खाद्य एवं औषधि प्रशासन (FDA) ने विमल इलायची के विज्ञापन को लेकर अभिनेता शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को नोटिस जारी किए हैं। FDA ने उत्पाद के प्रचार को लेकर अभिनेताओं को चेतावनी दी है। अभिनेता मुकेश खन्ना ने FDA की कार्रवाई का समर्थन किया है और कहा है कि अभिनेताओं को माफी मांगनी चाहिए।', '["Maharashtra FDA issued notices to Shah Rukh Khan, Ajay Devgn, and Tiger Shroff.", "The notices concern an advertisement for Vimal Elaichi.", "The FDA has issued a warning to the actors.", "Actor Mukesh Khanna backed the FDA''s action and called for an apology."]'::jsonb, '["महाराष्ट्र FDA ने शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को नोटिस जारी किए।", "नोटिस विमल इलायची के विज्ञापन से संबंधित हैं।", "FDA ने अभिनेताओं को चेतावनी जारी की है।", "अभिनेता मुकेश खन्ना ने FDA की कार्रवाई का समर्थन किया और माफी की मांग की।"]'::jsonb, 'Crime & Law', 'India', 0, 1, 1, 0, 0, 2, 'center', 50, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["The Indian Express"], "owners": ["Indian Express Group"]}, "right": {"count": 1, "sources": ["Punjab Kesari"], "owners": ["Punjab Kesari"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Punjab Kesari", "owner": "Punjab Kesari", "lean": "right", "language": "hi", "url": "https://www.punjabkesari.in/national/news/maharashtra-fda-shah-rukh-khan-ajay-devgn-tiger-shroff-vimal-elaichi-2369931", "headline": "शाहरुख - अजय - टाइगर की बढ़ी मुश्किलें , विमल इलायची विज्ञापन पर महाराष्ट्र FDA का नोटिस , जारी की चेतावनी - maharashtra fda shah rukh khan ajay devgn tiger shroff vimal elaichi"}, {"source": "The Indian Express", "owner": "Indian Express Group", "lean": "center", "language": "en", "url": "https://indianexpress.com/article/entertainment/bollywood/mukesh-khanna-fda-notices-shah-rukh-khan-ajay-devgn-tiger-shroff-vimal-ad-apologise-10838375", "headline": "Mukesh Khanna backs FDA notices to Shah Rukh, Ajay, Tiger over Vimal ad: ‘Apologise’"}]'::jsonb, '{"title": "FDA Notices Issued Over Vimal Elaichi Advertisement", "summary": "Maharashtra''s Food and Drug Administration (FDA) has issued notices to actors Shah Rukh Khan, Ajay Devgn, and Tiger Shroff regarding an advertisement for Vimal Elaichi. The FDA has warned the actors over their endorsement of the product. Actor Mukesh Khanna has supported the FDA''s action, stating the actors should apologize.", "summary_points": ["Maharashtra FDA issued notices to Shah Rukh Khan, Ajay Devgn, and Tiger Shroff.", "The notices concern an advertisement for Vimal Elaichi.", "The FDA has issued a warning to the actors.", "Actor Mukesh Khanna backed the FDA''s action and called for an apology."], "title_hi": "विमल इलायची विज्ञापन पर FDA ने जारी किए नोटिस", "summary_hi": "महाराष्ट्र के खाद्य एवं औषधि प्रशासन (FDA) ने विमल इलायची के विज्ञापन को लेकर अभिनेता शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को नोटिस जारी किए हैं। FDA ने उत्पाद के प्रचार को लेकर अभिनेताओं को चेतावनी दी है। अभिनेता मुकेश खन्ना ने FDA की कार्रवाई का समर्थन किया है और कहा है कि अभिनेताओं को माफी मांगनी चाहिए।", "summary_point